  "titleCn": "泰国数字平台贸易协会(TDPA)成立，Grab/Lazada/LINE/Shopee共同发起（11-21 热点重排）",
  "titleOrig": "Thailand Digital Platform Trade Association (TDPA) founded by Grab, Lazada, LINE MAN Wongnai, Shopee (泰国数字平台贸易协会成立)",
  "summary": "2026年2月27日，由Grab、Lazada、LINE MAN Wongnai和Shopee四大平台共同发起的泰国数字平台贸易协会(TDPA)正式成立，旨在推动泰国平台经济向平衡、透明、公平且符合全球标准的监管框架发展。协会将作为协调私营部门、政府与利益相关方的机制，制定透明度与公平竞争公共政策。印花T恤卖家将面临更规范的平台治理与披露要求。🟡黄色窗口（监管常态化，长期影响）。（印选 11-21 热点重排上架：库内真实历史热点复用，非新研究。）",
