  "titleOrig": "Thailand extends 7% VAT until Sep 2027（泰国7%增值税优惠延长至2027年9月30日，不恢复10%法定基准税率）",
  "summary": "泰国宣布不含地方税税率6.3%、含地方税后7%的增值税优惠延续至2027年9月30日，不恢复《税收法典》规定的10%法定基准税率。为TikTok Shop、Lazada、Shopee泰国站及在泰设实体的外资卖家提供未来12个月明确的税负预期，短期备货、营销投放无需重新调整税负模型，稳定跨境T恤定价环境。（印选 11-05 热点重排上架：库内真实历史热点复用，非新研究。）（印选 11-21 热点重排上架：库内真实历史热点复用，非新研究。）",
